import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"方法、幂等与缓存头","description":"","frontmatter":{"title":"方法、幂等与缓存头","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/http-semantics.md","filePath":"cs/http-semantics.md","lastUpdated":1789023840000}'),T={name:"cs/http-semantics.md"};function p(h,a,A,_,m,P){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="方法、幂等与缓存头" tabindex="-1">方法、幂等与缓存头 <a class="header-anchor" href="#方法、幂等与缓存头" aria-label="Permalink to &quot;方法、幂等与缓存头&quot;">​</a></h1><div class="epigraph"><p>方法约定对资源做什么；幂等与安全限制重试能否自动发生。缓存头告诉中间人这份表示能不能存、能存多久。</p><footer>—— 据 Fielding 等, RFC 9110, HTTP Semantics, 2022；Kurose and Ross</footer></div><p><a href="/cs/http">上一课</a>给出请求–响应：方法、目标、头、状态码。本课不重画一行请求。缺口是语义合同：GET 与 PUT 能否被代理重试、中间盒按什么头缓存。没有这些，后课 HTTP/2 多路只是换了帧，CDN 也不知道什么能复制。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/http">HTTP</a> 留下方法名。安全方法（GET、HEAD）不应有副作用；幂等方法（含 PUT、DELETE）同一请求重复一次与多次效果相当。POST 通常既不安全也不幂等，丢了不能由中间人盲目重放。<code>Cache-Control</code>、<code>ETag</code>、条件请求决定表示是否可复用。缺口是<strong>重试与缓存的合法性</strong>，不是 TLS 记录。</p><p><span class="marginnote">RFC 9110 把语义从具体传输版本里抽出来。HTTP/1.1 的连接复用与 HTTP/2 的流共享同一套方法含义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端与代理按方法决定：失败的 GET 可重试；失败的 POST 要应用层保证。缓存键通常是方法+目标+相关头；<code>no-store</code> 禁止保存，<code>max-age</code> 给出新鲜期，验证器用条件 GET 把带宽换成确认。本课不把 Cookie 与会话当缓存替代。</p>',8)),(e(),n(c,null,{default:o(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20METH%5B%22%E6%96%B9%E6%B3%95%E8%AF%AD%E4%B9%89%22%5D%20--%3E%20IDEM%5B%22%E6%98%AF%E5%90%A6%E5%B9%82%E7%AD%89%20%2F%20%E5%AE%89%E5%85%A8%22%5D%0A%20%20IDEM%20--%3E%20RETRY%5B%22%E4%B8%AD%E9%97%B4%E4%BA%BA%E5%8F%AF%E5%90%A6%E8%87%AA%E5%8A%A8%E9%87%8D%E8%AF%95%22%5D%0A%20%20HDR%5B%22%E7%BC%93%E5%AD%98%E5%A4%B4%22%5D%20--%3E%20STORE%5B%22%E6%98%AF%E5%90%A6%E5%AD%98%E5%82%A8%E4%B8%8E%E5%86%8D%E9%AA%8C%E8%AF%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>幂等把<a href="/cs/layering-e2e">端到端</a> 重试从传输层（TCP 重传是字节，不是「再做一次业务」）里拆出来：TCP 保证段到达，HTTP 才规定「到达两次」是否事故。缓存把表示从源站路径上拿下来，后课 CDN 只是把缓存放到边上。TLS 入口仍只保护信道，不改方法语义。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 REST 成熟度模型当协议，不引入 GraphQL。一条 TCP 连接上如何避免队头阻塞，下一课 HTTP/2。</p><p>后课默认：方法带幂等与缓存合同。多请求并行的传输映射是下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RFC 9110：安全/幂等约束重试；缓存头约束存储。</li><li>传输重传 ≠ 应用重试。</li><li>多路复用下一课 HTTP/2。</li><li>出处：RFC 9110；Kurose and Ross。</li></ul>',7))])}const f=s(T,[["render",p]]);export{D as __pageData,f as default};
